"""Classical Davenport constant via the kernel-cover model over Z/mZ."""
from __future__ import annotations
from itertools import product
from typing import Iterable, List, Optional, Sequence, Tuple


def valid_weightings(weight_set: Sequence[int], n: int, m: int) -> Iterable[Tuple[int, ...]]:
    alphabet: List[int] = sorted({0} | {w % m for w in weight_set})
    for a in product(alphabet, repeat=n):
        if any(c % m != 0 for c in a):
            yield a


def phi(a: Sequence[int], x: Sequence[int], m: int) -> int:
    return sum(ai * xi for ai, xi in zip(a, x)) % m


def kernel_cover(weight_set: Sequence[int], n: int, m: int) -> bool:
    for x in product(range(m), repeat=n):
        if not any(phi(a, x, m) == 0 for a in valid_weightings(weight_set, len(x), m)):
            return False
    return True


def weighted_davenport(weight_set: Sequence[int], m: int, n_max: int = 10) -> Optional[int]:
    for n in range(1, n_max + 1):
        if kernel_cover(weight_set, n, m):
            return n
    return None


if __name__ == "__main__":
    print("Classical Davenport constant D_{1}(Z/mZ) should equal m:")
    for m in range(2, 7):
        d = weighted_davenport([1], m)
        print(f"  m={m}: D = {d}  (expected {m})  {'OK' if d == m else 'MISMATCH'}")

"""Weighted Davenport constants shrink as the weight set grows (over Z/mZ)."""
from __future__ import annotations
from itertools import product
from typing import Iterable, List, Optional, Sequence, Tuple


def _gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def valid_weightings(weight_set: Sequence[int], n: int, m: int) -> Iterable[Tuple[int, ...]]:
    alphabet: List[int] = sorted({0} | {w % m for w in weight_set})
    for a in product(alphabet, repeat=n):
        if any(c % m != 0 for c in a):
            yield a


def phi(a: Sequence[int], x: Sequence[int], m: int) -> int:
    return sum(ai * xi for ai, xi in zip(a, x)) % m


def kernel_cover(weight_set: Sequence[int], n: int, m: int) -> bool:
    for x in product(range(m), repeat=n):
        if not any(phi(a, x, m) == 0 for a in valid_weightings(weight_set, len(x), m)):
            return False
    return True


def weighted_davenport(weight_set: Sequence[int], m: int, n_max: int = 10) -> Optional[int]:
    for n in range(1, n_max + 1):
        if kernel_cover(weight_set, n, m):
            return n
    return None


if __name__ == "__main__":
    for m in (5, 6, 7):
        units = [a for a in range(1, m) if _gcd(a, m) == 1]
        print(f"Z/{m}Z:")
        for name, w in [("{1}", [1]), ("{1,-1}", sorted({1, m - 1})),
                        ("units", units), ("all nonzero", list(range(1, m)))]:
            print(f"    W = {name:<12} D_W = {weighted_davenport(w, m)}")

"""Cross-check: the pointwise kernel-cover property equals the set-cover identity."""
from __future__ import annotations
from itertools import product
from typing import FrozenSet, Iterable, List, Sequence, Tuple


def valid_weightings(weight_set: Sequence[int], n: int, m: int) -> Iterable[Tuple[int, ...]]:
    alphabet: List[int] = sorted({0} | {w % m for w in weight_set})
    for a in product(alphabet, repeat=n):
        if any(c % m != 0 for c in a):
            yield a


def phi(a: Sequence[int], x: Sequence[int], m: int) -> int:
    return sum(ai * xi for ai, xi in zip(a, x)) % m


def kernel_cover(weight_set: Sequence[int], n: int, m: int) -> bool:
    for x in product(range(m), repeat=n):
        if not any(phi(a, x, m) == 0 for a in valid_weightings(weight_set, len(x), m)):
            return False
    return True


def kernel_of(a: Sequence[int], m: int) -> FrozenSet[Tuple[int, ...]]:
    return frozenset(x for x in product(range(m), repeat=len(a)) if phi(a, x, m) == 0)


def union_covers_all(weight_set: Sequence[int], n: int, m: int) -> bool:
    union: set = set()
    for a in valid_weightings(weight_set, n, m):
        union |= kernel_of(a, m)
    return len(union) == m ** n


if __name__ == "__main__":
    for m in (3, 4, 5):
        for n in range(1, 4):
            a = kernel_cover([1], n, m)
            b = union_covers_all([1], n, m)
            print(f"Z/{m}Z n={n}: pointwise={a} set-cover={b} agree={a == b}")

