"""Bar chart: weighted Davenport constant vs. weight set for several moduli."""
from itertools import product
import matplotlib.pyplot as plt


def _gcd(a, b):
    while b:
        a, b = b, a % b
    return a


def valid(weight_set, n, m):
    alphabet = sorted({0} | {w % m for w in weight_set})
    for a in product(alphabet, repeat=n):
        if any(c % m != 0 for c in a):
            yield a


def cover(weight_set, n, m):
    return all(any(sum(ai * xi for ai, xi in zip(a, x)) % m == 0
                   for a in valid(weight_set, n, m))
               for x in product(range(m), repeat=n))


def dW(weight_set, m, n_max=10):
    for n in range(1, n_max + 1):
        if cover(weight_set, n, m):
            return n
    return n_max + 1


moduli = [5, 6, 7]
labels = ["{1}", "{1,-1}", "units", "all nonzero"]
fig, ax = plt.subplots(figsize=(8, 5))
width = 0.2
for i, m in enumerate(moduli):
    units = [a for a in range(1, m) if _gcd(a, m) == 1]
    sets = [[1], sorted({1, m - 1}), units, list(range(1, m))]
    vals = [dW(s, m) for s in sets]
    ax.bar([x + i * width for x in range(len(labels))], vals, width, label=f"Z/{m}Z")
ax.set_xticks([x + width for x in range(len(labels))])
ax.set_xticklabels(labels)
ax.set_ylabel("weighted Davenport constant $D_W$")
ax.set_title("Larger weight sets yield smaller Davenport constants")
ax.legend()
plt.tight_layout()
plt.savefig("davenport_threshold.png", dpi=150)
print("wrote davenport_threshold.png")
